  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": [
    "C01","C02","C03","C04","C05","C06","C07","C08","C09","C10",
    "C11","C12","C13","C14","C15","C16","C17","C18","C19","C20",
    "C21","C33","C35","C80"
  ],
  "contradictory_card_ids": ["C83","C84","C79","C85","C86"],
  "prediction_basis_card_ids": ["C01","C18","C33","C35","C07","C10","C06","C13"],
  "claims": [
    {
      "claim": "All L1 gold records report absolute or systemic bioavailability values or qualitative outcomes at or above about 35% (alfuzosin 49%, rigosertib 35%/34.8%, GDC-0810 ~45%, indomethacin 76-80%, midodrine 90-100%, colchicine 44-55%, omeprazole ~100%, 5-HTP 49%, loratadine good), so the gold evidence direction uniformly supports F >= 20%.",
      "card_ids": [
        "C01","C02","C03","C04","C05","C06","C07","C08","C09","C10",
        "C11","C12","C13","C14","C15","C16","C17","C18","C19","C20","C21"
      ]
    },
    {
      "claim": "The closest gold context, alfuzosin (dimethoxy-aminoheteroaromatic with amide side chain), has F=49% under fed conditions; the query shares dimethoxyheteroaromatic and amide motifs, supporting transfer to F >= 20%.",
      "card_ids": ["C01","C18","C33","C35"]
    },
    {
      "claim": "L6 hepatic-clearance records are analog HLM/hepatocyte CLint values and CYP phenotyping, not direct F measurements; values range from low (14-19 µL/min/mg) to high (42-64 µL/min/mg), and C80 shows indomethacin has HLM glucuronidation CLint 30.1 µL/min/mg yet F=76-80%, so moderate intrinsic clearance does not affirmatively establish F < 20%.",
      "card_ids": ["C77","C78","C79","C80","C81","C82","C83","C84","C85","C86","C87","C88"]
    },
    {
      "claim": "No L6 record reports an absolute F value; high analog CLint values (C83, C84, C79, C85, C86) are only mechanistic risk factors and cannot by themselves affirm F < 20%.",
      "card_ids": ["C83","C84","C79","C85","C86"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C77","C78","C79","C80","C81","C82","C83","C84","C85","C86","C87","C88"]
    }
  ],
  "evidence_gaps": [
    "No direct query-specific absolute oral bioavailability measurement is available.",
    "No query-specific hepatic clearance or metabolic stability measurement is available; L6 records are for analogs with moderate transfer likelihood.",
    "No query-specific solubility, permeability, or efflux measurement is available.",
    "The query has no reported external condition (fasted/fed, modified release, disease), limiting direct transfer of condition-specific gold contexts.",
    "L6 CLint values are not direct F measurements and cannot affirmatively establish F < 20%.",
    "Structural transfer from gold contexts is imperfect because the query is larger and more lipophilic than the closest context (alfuzosin)."
  ],
  "decision_summary": "L6 adds analog hepatic-clearance and metabolic-stability records, but no direct F<20% outcome and no query-specific measurement; CLint values are mixed and C80 shows moderate HLM CLint with high F. L1/L2 gold and context records uniformly support F>=20%, with the closest context (alfuzosin) at 49%. The low physicochemical prior and analog metabolic liabilities are insufficient to overturn the high prediction; prediction remains high with moderate confidence."
}

